def feature(s):
    v = s.get('volume_per_atom_A3')
    if v is None:
        v = s.get('basic_structure_statistics', {}).get('volume_per_atom_A3')
    return float(v) if v is not None and math.isfinite(v) and v > 0 else 0.0

def feature(s):
    p = s.get('element_properties', {})
    total = 0.0
    weight = 0.0
    for e, x in s.get('composition', {}).items():
        r = p.get(e, {}).get('covalent_radius_A')
        if r is not None and r > 0 and x > 0:
            total += x * r ** 3
            weight += x
    v = s.get('volume_per_atom_A3')
    if v is None:
        v = s.get('basic_structure_statistics', {}).get('volume_per_atom_A3')
    if weight <= 0 or v is None or v <= 0 or not math.isfinite(v):
        return 0.0
    return float(4.0 * math.pi * total / (3.0 * weight * v))

def feature(s):
    sites = s.get('sites', ())
    n = len(sites)
    nearest = [math.inf for t in sites]
    for b in s.get('neighbors', ()):
        i = b['i']
        d = b.get('distance_A')
        if 0 <= i < n and d is not None and d > 0 and d < nearest[i]:
            nearest[i] = d
    weight = 0.0
    first = 0.0
    second = 0.0
    for i in range(n):
        o = sites[i].get('occupancy')
        o = 1.0 if o is None else max(0.0, o)
        if math.isfinite(nearest[i]):
            weight += o
            first += o * nearest[i]
            second += o * nearest[i] ** 2
    if weight <= 0 or first <= 0:
        return 0.0
    mean = first / weight
    return float(math.sqrt(max(0.0, second / weight - mean * mean)) / mean)

def feature(s):
    sites = s.get('sites', ())
    p = s.get('element_properties', {})
    n = len(sites)
    r = [p.get(t.get('element'), {}).get('covalent_radius_A') for t in sites]
    o = [max(0.0, t.get('occupancy') if t.get('occupancy') is not None else 1.0) for t in sites]
    amounts = {}
    for i in range(n):
        if r[i] is not None and r[i] > 0:
            e = sites[i].get('element')
            amounts[e] = amounts.get(e, 0.0) + o[i]
    atom_weight = sum(amounts.values())
    total = 0.0
    unlike = 0.0
    for b in s.get('neighbors', ()):
        i = b['i']
        j = b['j']
        d = b.get('distance_A')
        if 0 <= i < n and 0 <= j < n and d is not None and d > 0 and r[i] is not None and r[j] is not None and r[i] > 0 and r[j] > 0 and d <= 1.25 * (r[i] + r[j]):
            w = o[i] * o[j]
            total += w
            if sites[i].get('element') != sites[j].get('element'):
                unlike += w
    if total <= 0 or atom_weight <= 0:
        return 0.0
    expected = 1.0 - sum((x / atom_weight) ** 2 for x in amounts.values())
    return float(unlike / total - expected)

def feature(s):
    p = s.get('element_properties', {})
    total = 0.0
    weight = 0.0
    for e, x in s.get('composition', {}).items():
        value = p.get(e, {}).get('valence_electrons')
        if value is not None and x > 0:
            total += x * value
            weight += x
    v = s.get('volume_per_atom_A3')
    if v is None:
        v = s.get('basic_structure_statistics', {}).get('volume_per_atom_A3')
    if weight <= 0 or v is None or v <= 0 or not math.isfinite(v):
        return 0.0
    return float(total / (weight * v))

