def feature(s):
    p = s.get('element_properties', {})
    values = []
    for e, x in s.get('composition', {}).items():
        q = p.get(e, {})
        ion = q.get('first_ionization_energy_eV')
        affinity = q.get('electron_affinity_eV')
        if x > 0 and ion is not None and affinity is not None and math.isfinite(ion) and math.isfinite(affinity) and ion > affinity:
            values = values + [(x, 0.5 * (ion + affinity), ion - affinity)]
    weight = sum(t[0] for t in values)
    if weight <= 0:
        return 0.0
    total = 0.0
    for i in range(len(values)):
        for j in range(i + 1, len(values)):
            a = values[i]
            b = values[j]
            total += 2.0 * a[0] * b[0] * (a[1] - b[1]) ** 2 / (a[2] + b[2])
    return float(total / (weight * weight))
